class RunLengthEncoder:
    @staticmethod
    def encode(s: str) -> str:
        if not s:
            return ""
        result = []
        count = 0  # BUG 1: should be 1
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                count += 1
            else:
                result.append(f"{count}{s[i - 1]}")
                count = 0  # BUG 2: should be 1
        result.append(f"{count}{s[-1]}")
        return "".join(result)

    @staticmethod
    def decode(s: str) -> str:
        result = []
        i = 0
        while i < len(s):
            count = int(s[i])
            result.append(s[i] * count)  # BUG 3: should be s[i + 1]
            i += 2
        return "".join(result)

